}

fn main() {
    let args = Args::parse();

    // Validate required groups
    if args.quality.is_none() && !args.lossless && args.max_size.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>");
        eprintln!("  <--output <OUTPUT>|--same-folder-as-input>");
        eprintln!("\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...");
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if args.output.is_none() && !args.same_folder_as_input {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <--output <OUTPUT>|--same-folder-as-input>");
        eprintln!("\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...");
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if args.files.is_empty() {
        eprintln!("No files to compress");
        std::process::exit(0);
    }

    // Validate min_savings
    let min_savings_opt: Option<MinSavings> = if let Some(ms) = &args.min_savings {
        match parse_min_savings(ms) {
