fn parse_byte_size(s: &str) -> Result<u64, String> {
    let trimmed = s.trim();
    // must not have leading space; but we already trimmed; original rejects " 100KB" with leading space
    if s != trimmed {
        // original had leading space: it fails with cannot parse float from empty string
        // emulate exactly: for " invalid" -> error: couldn't parse " invalid" into a ByteSize, cannot parse float from empty string
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    // Use simple parser that mimics byte-unit crate behavior for max-size
    // Accept formats: number + unit, unit can be B, KB, KiB, MB, MiB, GB, GiB, TB, TiB, K, M, G, T, etc case-insensitive, with optional space between number and unit? Original allowed "100 KB" with space and "100kb" lower case etc.
    // Let's implement: split into numeric part and unit part.
    // Find where numeric ends. Numeric can contain '.'.
    // If fails, produce errors similar to original.
    // For "invalid" -> fails to parse float from empty string? That suggests it tried to parse numeric part but got empty.
    // For "100invalid" -> fails to parse unit "invalid"
    // So implement accordingly.

    // Find first non-numeric/dot
    let mut num_end = 0;
    let chars: Vec<char> = trimmed.chars().collect();
    let mut dot_seen = false;
    let mut has_digit = false;
    for (i, c) in chars.iter().enumerate() {
        if c.is_ascii_digit() {
            has_digit = true;
            num_end = i+1;
        } else if *c == '.' && !dot_seen {
            dot_seen = true;
            num_end = i+1;
        } else {
            break;
        }
    }
    if !has_digit {
        // No numeric part
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    let num_str = &trimmed[..num_end];
    let unit_str = trimmed[num_end..].trim(); // unit may have leading space trimmed
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s))?;
    // Determine multiplier
    let unit_lower = unit_str.to_lowercase();
    // Remove possible spaces already trimmed, but unit may be empty => bytes
    let mult : f64 = if unit_lower.is_empty() || unit_lower=="b" {
        1.0
    } else if unit_lower=="kb" || unit_lower=="k" {
        1000.0
    } else if unit_lower=="kib" {
        1024.0
    } else if unit_lower=="mb" || unit_lower=="m" {
        1000.0*1000.0
    } else if unit_lower=="mib" {
        1024.0*1024.0
    } else if unit_lower=="gb" || unit_lower=="g" {
        1000.0*1000.0*1000.0
    } else if unit_lower=="gib" {
        1024.0*1024.0*1024.0
    } else if unit_lower=="tb" || unit_lower=="t" {
        1000.0*1000.0*1000.0*1000.0
    } else if unit_lower=="tib" {
        1024.0*1024.0*1024.0*1024.0
    } else if unit_lower=="pb" || unit_lower=="p" {
        1000.0*1000.0*1000.0*1000.0*1000.0
    } else if unit_lower=="pib" {
        1024.0*1024.0*1024.0*1024.0*1024.0
    } else {
        // unknown unit: original says Failed to parse unit "inv..."
        // It shows truncated unit 3 chars? For "invalid" it showed "inv..."
        // For ",5KB" it showed ",5K..."
        // Let's produce similar but generic.
        // The error format: Invalid size format: couldn't parse "invalid" into a known SI unit, Failed to parse unit "inv..."
        // For max-size.
        let display_unit = if unit_str.len() > 3 { format!("{}...", &unit_str[..3]) } else { unit_str.to_string() };
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a known SI unit, Failed to parse unit \"{}\"", &trimmed[num_end..], display_unit));
    };
    let bytes = num * mult;
    Ok(bytes as u64)
}

