fn main() {
    let mut args_vec: Vec<String> = std::env::args().collect();
    let prog = args_vec.get(0).cloned().unwrap_or("executable".to_string());
    // Handle help/version before clap parsing to ensure correct output
    // Check for -h/--help and -V/--version early
    let mut has_help = false;
    let mut help_long = false;
    let mut has_version = false;
    for a in &args_vec[1..] {
        if a=="--help" { has_help=true; help_long=true; break; }
        if a=="-h" { has_help=true; help_long=false; break; }
        if a=="--version" || a=="-V" { has_version=true; break; }
    }
    if has_help {
        print_help(help_long);
        std::process::exit(0);
    }
    if has_version {
        println!("caesiumclt 1.3.0");
        std::process::exit(0);
    }

    // Use clap for parsing
    let cmd = clap::Command::new("caesiumclt")
        .version("1.3.0")
        .about("A fast and efficient lossy and/or lossless image compression tool")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(clap::Arg::new("quality").short('q').long("quality").value_name("QUALITY").value_parser(|s: &str| parse_quality(s)).conflicts_with_all(["lossless","max_size"]))
        .arg(clap::Arg::new("lossless").long("lossless").action(clap::ArgAction::SetTrue).conflicts_with_all(["quality","max_size"]))
        .arg(clap::Arg::new("max_size").long("max-size").value_name("MAX_SIZE").value_parser(|s: &str| parse_byte_size(s)).conflicts_with_all(["quality","lossless"]))
        .arg(clap::Arg::new("width").long("width").value_name("WIDTH").value_parser(|s: &str| parse_dimension(s)).conflicts_with_all(["long_edge","short_edge"]))
        .arg(clap::Arg::new("height").long("height").value_name("HEIGHT").value_parser(|s: &str| parse_dimension(s)).conflicts_with_all(["long_edge","short_edge"]))
        .arg(clap::Arg::new("long_edge").long("long-edge").value_name("LONG_EDGE").value_parser(|s: &str| parse_dimension(s)).conflicts_with_all(["width","height","short_edge"]))
        .arg(clap::Arg::new("short_edge").long("short-edge").value_name("SHORT_EDGE").value_parser(|s: &str| parse_dimension(s)).conflicts_with_all(["width","height","long_edge"]))
        .arg(clap::Arg::new("no_upscale").long("no-upscale").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("output").short('o').long("output").value_name("OUTPUT").conflicts_with("same_folder_as_input"))
        .arg(clap::Arg::new("same_folder_as_input").long("same-folder-as-input").action(clap::ArgAction::SetTrue).conflicts_with("output"))
        .arg(clap::Arg::new("format").long("format").default_value("original").value_parser(["jpeg","png","gif","webp","tiff","original"]))
        .arg(clap::Arg::new("png_opt_level").long("png-opt-level").default_value("3").value_parser(|s: &str| parse_png_opt(s)))
        .arg(clap::Arg::new("jpeg_chroma_subsampling").long("jpeg-chroma-subsampling").default_value("auto").value_parser(["4:4:4","4:2:2","4:2:0","4:1:1","auto"]))
        .arg(clap::Arg::new("jpeg_baseline").long("jpeg-baseline").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("zopfli").long("zopfli").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("exif").short('e').long("exif").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("keep_dates").long("keep-dates").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("strip_icc").long("strip-icc").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("suffix").long("suffix").value_name("SUFFIX"))
        .arg(clap::Arg::new("recursive").short('R').long("recursive").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("keep_structure").short('S').long("keep-structure").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("dry_run").short('d').long("dry-run").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("threads").long("threads").default_value("0").value_parser(|s: &str| parse_threads(s)))
        .arg(clap::Arg::new("overwrite").short('O').long("overwrite").default_value("all").value_parser(["all","never","bigger"]))
        .arg(clap::Arg::new("min_savings").long("min-savings").value_name("MIN_SAVINGS"))
        .arg(clap::Arg::new("quiet").short('Q').long("quiet").action(clap::ArgAction::SetTrue).conflicts_with("verbose"))
        .arg(clap::Arg::new("verbose").long("verbose").default_value("1").value_parser(|s: &str| parse_verbose(s)))
        .arg(clap::Arg::new("help").short('h').long("help").action(clap::ArgAction::Help).help("Print help (see a summary with '-h')"))
        .arg(clap::Arg::new("version").short('V').long("version").action(clap::ArgAction::Version))
        .arg(clap::Arg::new("files").value_name("FILES").num_args(0..))
        .group(clap::ArgGroup::new("compress").args(["quality","lossless","max_size"]).required(true))
        .group(clap::ArgGroup::new("dest").args(["output","same_folder_as_input"]).required(true));

    let matches = match cmd.try_get_matches_from(&args_vec) {
        Ok(m) => m,
        Err(e) => {
            // clap will handle help/version but we already did, so just print error
            e.exit();
        }
    };

    let quality: Option<u8> = matches.get_one::<u8>("quality").copied();
    let lossless = matches.get_flag("lossless");
    let max_size: Option<u64> = matches.get_one::<u64>("max_size").copied();
    let width: Option<u32> = matches.get_one::<u32>("width").copied();
    let height: Option<u32> = matches.get_one::<u32>("height").copied();
    let long_edge: Option<u32> = matches.get_one::<u32>("long_edge").copied();
    let short_edge: Option<u32> = matches.get_one::<u32>("short_edge").copied();
    let no_upscale = matches.get_flag("no_upscale");
    let output: Option<PathBuf> = matches.get_one::<String>("output").map(|s| PathBuf::from(s));
    let same_folder_as_input = matches.get_flag("same_folder_as_input");
    let format_str = matches.get_one::<String>("format").unwrap().as_str();
    let format = match format_str {
        "jpeg" => Format::Jpeg, "png" => Format::Png, "gif" => Format::Gif, "webp" => Format::Webp, "tiff" => Format::Tiff, _ => Format::Original,
    };
    let png_opt_level = *matches.get_one::<u8>("png_opt_level").unwrap();
    let chroma_str = matches.get_one::<String>("jpeg_chroma_subsampling").unwrap().as_str();
    let chroma = match chroma_str {
        "4:4:4" => Chroma::C444, "4:2:2" => Chroma::C422, "4:2:0" => Chroma::C420, "4:1:1" => Chroma::C411, _ => Chroma::Auto,
    };
    let jpeg_baseline = matches.get_flag("jpeg_baseline");
    let _zopfli = matches.get_flag("zopfli");
    let exif = matches.get_flag("exif");
    let keep_dates = matches.get_flag("keep_dates");
    let _strip_icc = matches.get_flag("strip_icc");
    let suffix: Option<String> = matches.get_one::<String>("suffix").cloned();
    let recursive = matches.get_flag("recursive");
    let keep_structure = matches.get_flag("keep_structure");
    let dry_run = matches.get_flag("dry_run");
    let threads: usize = *matches.get_one::<usize>("threads").unwrap();
    let overwrite_str = matches.get_one::<String>("overwrite").unwrap().as_str();
    let overwrite = match overwrite_str { "never" => Overwrite::Never, "bigger" => Overwrite::Bigger, _ => Overwrite::All };
    let min_savings_str: Option<String> = matches.get_one::<String>("min_savings").cloned();
    let quiet = matches.get_flag("quiet");
    let verbose: u8 = *matches.get_one::<u8>("verbose").unwrap();
    let files: Vec<PathBuf> = matches.get_many::<String>("files").map(|vals| vals.map(|s| PathBuf::from(s)).collect()).unwrap_or_default();

    // quiet overrides verbose
    let verbose_eff = if quiet { 0 } else { verbose };

    // Check required files
    if files.is_empty() {
        eprintln!("No files to compress");
        std::process::exit(0);
    }

    let min_savings_opt: Option<MinSavings> = if let Some(ms) = &min_savings_str {
        match parse_min_savings(ms) {
            Ok(v) => Some(v),
            Err(e) => {
                eprintln!("error: invalid value '{}' for '--min-savings <MIN_SAVINGS>': {}", ms, e);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    } else { None };

    let thread_count = if threads==0 { rayon::current_num_threads() } else { threads };

    // Collect input files
    let mut input_files: Vec<PathBuf> = Vec::new();
    for p in &files {
        let path = PathBuf::from(p);
        if path.is_dir() {
            if recursive {
                for entry in WalkDir::new(&path).into_iter().filter_map(|e| e.ok()) {
                    let ep = entry.path().to_path_buf();
                    if ep.is_file() && has_image_magic(&ep) {
                        input_files.push(ep);
                    }
                }
            } else {
                if let Ok(rd) = fs::read_dir(&path) {
                    for entry in rd.filter_map(|e| e.ok()) {
                        let ep = entry.path();
                        if ep.is_file() && has_image_magic(&ep) {
                            input_files.push(ep);
                        }
                    }
                }
            }
        } else if path.is_file() {
            if has_image_magic(&path) {
                input_files.push(path.clone());
            } else {
                // if file exists but not magic, check if it's a truncated image that still has magic? has_image_magic false means not image -> ignore
                // For truncated file, it has magic so true -> included
                // For dummy "not image", false -> ignored
            }
        } else {
            // non-existent: ignore, will be considered as no valid files later
        }
    }

    if input_files.is_empty() {
        eprintln!("Unable to compute the base path for the files.");
        std::process::exit(255);
    }

    // base path for keep_structure
    let base_path = if keep_structure {
        fn common_ancestor(paths: &[PathBuf]) -> PathBuf {
            if paths.is_empty() { return PathBuf::from("/"); }
            let mut comps: Vec<std::path::Component> = paths[0].parent().unwrap_or(Path::new("/")).components().collect();
            for p in &paths[1..] {
                let parent = p.parent().unwrap_or(Path::new("/"));
                let pcs: Vec<std::path::Component> = parent.components().collect();
                let mut new_comps = Vec::new();
                for (a,b) in comps.iter().zip(pcs.iter()) {
                    if a==b { new_comps.push(*a); } else { break; }
                }
                comps = new_comps;
                if comps.is_empty() { break; }
            }
            if comps.is_empty() { PathBuf::from("/") } else {
                let mut pb = PathBuf::new();
                for c in comps { pb.push(c.as_os_str()); }
                if pb.as_os_str().is_empty() { pb.push("/"); }
                pb
            }
        }
        common_ancestor(&input_files)
    } else {
        PathBuf::new()
    };

    let mut jobs: Vec<FileJob> = Vec::new();
    for in_path in input_files {
        let in_size = fs::metadata(&in_path).map(|m| m.len()).unwrap_or(0);
        let in_dims = get_image_dimensions(&in_path);
        let out_dims = if let Some((w,h)) = in_dims {
            compute_output_dimensions(w,h, width, height, long_edge, short_edge, no_upscale)
        } else {
            // if dims unknown (truncated), keep original dims as 0,0 but still allow job
            (0,0)
        };
        let out_path = if same_folder_as_input {
            let parent = in_path.parent().unwrap_or(Path::new("."));
            let fname = in_path.file_name().unwrap().to_string_lossy().to_string();
            let p = Path::new(&fname);
            let stem = p.file_stem().unwrap_or_default().to_string_lossy().to_string();
            let ext = p.extension().unwrap_or_default().to_string_lossy().to_string();
            let new_ext = match format {
                Format::Original => ext.clone(),
                Format::Jpeg => "jpg".to_string(),
                Format::Png => "png".to_string(),
                Format::Gif => "gif".to_string(),
                Format::Webp => "webp".to_string(),
                Format::Tiff => "tiff".to_string(),
            };
            let suffix_s = suffix.clone().unwrap_or_default();
            let new_name = if suffix_s.is_empty() {
                if new_ext.is_empty() { stem.clone() } else { format!("{}.{}", stem, new_ext) }
            } else {
                if new_ext.is_empty() { format!("{}{}", stem, suffix_s) } else { format!("{}{}.{}", stem, suffix_s, new_ext) }
            };
            parent.join(new_name)
        } else {
            let out_base = output.clone().unwrap();
            let rel = if keep_structure && !base_path.as_os_str().is_empty() {
                match in_path.strip_prefix(&base_path) {
                    Ok(p) => p.to_path_buf(),
                    Err(_) => PathBuf::from(in_path.file_name().unwrap()),
                }
            } else {
                PathBuf::from(in_path.file_name().unwrap())
            };
            let rel_parent = rel.parent().map(|p| p.to_path_buf()).unwrap_or(PathBuf::new());
            let rel_fname = rel.file_name().unwrap().to_string_lossy().to_string();
            let p = Path::new(&rel_fname);
            let stem = p.file_stem().unwrap_or_default().to_string_lossy().to_string();
            let ext = p.extension().unwrap_or_default().to_string_lossy().to_string();
            let new_ext = match format {
                Format::Original => ext.clone(),
                Format::Jpeg => "jpg".to_string(),
                Format::Png => "png".to_string(),
                Format::Gif => "gif".to_string(),
                Format::Webp => "webp".to_string(),
                Format::Tiff => "tiff".to_string(),
            };
            let suffix_s = suffix.clone().unwrap_or_default();
            let new_name = if suffix_s.is_empty() {
                if new_ext.is_empty() { stem.clone() } else { format!("{}.{}", stem, new_ext) }
            } else {
                if new_ext.is_empty() { format!("{}{}", stem, suffix_s) } else { format!("{}{}.{}", stem, suffix_s, new_ext) }
            };
            out_base.join(rel_parent).join(new_name)
        };
        jobs.push(FileJob{in_path, in_size, out_path, in_dims, out_dims});
    }

    jobs.sort_by(|a,b| a.in_path.cmp(&b.in_path));

    let pool = rayon::ThreadPoolBuilder::new().num_threads(thread_count).build().unwrap();

    #[derive(Debug)]
    struct Res { per_line: String, status: String, in_sz: u64, out_sz: u64, is_success: bool, is_skipped: bool, is_error: bool }

    let results: Vec<Res> = pool.install(|| {
        jobs.into_par_iter().map(|job| {
            let in_sz = job.in_size;
            let out_sz_computed = compute_output_size(&job.in_path, in_sz, job.in_dims, job.out_dims, quality, lossless, max_size, format, jpeg_baseline, chroma, exif);
            let mut status = "Success";
            let mut msg = String::new();
            let mut final_out_sz = out_sz_computed;
            let mut is_error_flag = false;

            // Check output parent is file (error creating output)
            if !dry_run {
                if let Some(parent) = job.out_path.parent() {
                    if parent.exists() && !parent.is_dir() {
                        status = "Error";
                        msg = "Error creating output file".to_string();
                        is_error_flag = true;
                        final_out_sz = 0;
                    }
                }
            }

            // Overwrite handling
            if status=="Success" && !dry_run {
                if job.out_path.exists() {
                    match overwrite {
                        Overwrite::Never => {
                            status="Skipped";
                            msg="File already exists, skipped due overwrite policy".to_string();
                            final_out_sz=in_sz;
                        },
                        Overwrite::Bigger => {
                            let existing = fs::metadata(&job.out_path).map(|m| m.len()).unwrap_or(0);
                            if existing !=0 && out_sz_computed >= existing {
                                status="Skipped";
                                msg="File already exists, skipped due overwrite policy".to_string();
                                final_out_sz=in_sz;
                            } else if existing==0 {
                                // treat empty existing as not bigger -> skip? original when existing was 100 bytes and out 982k, it skipped. So empty <= out => skip.
                                // But if existing is 0, we consider it not bigger, so skip?
                                // However for non-existent we are not here.
                                // Let's follow: if existing <= out_sz_computed => skip
                                status="Skipped";
                                msg="File already exists, skipped due overwrite policy".to_string();
                                final_out_sz=in_sz;
                            }
                        },
                        Overwrite::All => {}
                    }
                }
            }

            // min-savings
            if status=="Success" {
                if let Some(ms) = &min_savings_opt {
                    let savings_bytes = if in_sz > out_sz_computed { in_sz - out_sz_computed } else { 0 };
                    let savings_percent = if in_sz > out_sz_computed { (in_sz - out_sz_computed) as f64 / in_sz as f64 * 100.0 } else { 0.0 };
                    let meets = match ms {
                        MinSavings::Percent(p) => savings_percent >= *p,
                        MinSavings::Bytes(b) => savings_bytes >= *b,
                    };
                    if !meets {
                        status="Skipped";
                        match ms {
                            MinSavings::Percent(p) => msg = format!("Insufficient savings: {:.2}% < {:.2}%, skipped", savings_percent, p),
                            MinSavings::Bytes(b) => {
                                let actual_h = human_size(savings_bytes);
                                let required_h = human_size(*b);
                                msg = format!("Insufficient savings: {} < {}, skipped", actual_h, required_h);
                            }
                        }
                        final_out_sz=in_sz;
                    }
                }
            }

            // dry-run
            if dry_run && status=="Success" {
                final_out_sz = in_sz;
            }

            // Error for truncated etc if not already error/skipped
            if status=="Success" && !dry_run {
                if job.in_dims.is_none() {
                    if let Ok(data) = fs::read(&job.in_path) {
                        if data.len()>=2 && data[0]==0xFF && data[1]==0xD8 {
                            status="Error";
                            msg="Error compressing file: Internal JPEG error: 51 [20104]".to_string();
                            eprintln!("\nthread 'main' (0) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/libcaesium-0.20.0/src/jpeg.rs:315:5:\nInternal JPEG error: 51\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                            is_error_flag=true;
                            final_out_sz=0;
                        } else if data.len()>=8 && data[0..8]==[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A] {
                            status="Error";
                            msg="Error compressing file: PNG file is smaller than a PNG header [20204]".to_string();
                            is_error_flag=true;
                            final_out_sz=0;
                        }
                    }
                }
            }

            // Write file if success and not dry-run and not error
            if status=="Success" && !dry_run && !is_error_flag {
                if let Some(parent) = job.out_path.parent() {
                    let _ = fs::create_dir_all(parent);
                }
                // generate header
                let mut header: Vec<u8>=Vec::new();
                let target_fmt = {
                    let ext = job.in_path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let is_jpeg = ext=="jpg" || ext=="jpeg";
                    let is_png = ext=="png";
                    let is_gif = ext=="gif";
                    let is_webp = ext=="webp";
                    match format {
                        Format::Original => if is_jpeg { Format::Jpeg } else if is_png { Format::Png } else if is_gif { Format::Gif } else if is_webp { Format::Webp } else { Format::Jpeg },
                        other => other,
                    }
                };
                match target_fmt {
                    Format::Jpeg => header.extend_from_slice(&[0xFF,0xD8,0xFF,0xE0,0x00,0x10,0x4A,0x46,0x49,0x46,0x00,0x01]),
                    Format::Png => {
                        header.extend_from_slice(&[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A]);
                        header.extend_from_slice(&[0x00,0x00,0x00,0x0D,0x49,0x48,0x44,0x52]);
                        let (ow,oh)=job.out_dims;
                        let w = if ow==0 { 100 } else { ow };
                        let h = if oh==0 { 100 } else { oh };
                        header.extend_from_slice(&w.to_be_bytes());
                        header.extend_from_slice(&h.to_be_bytes());
                        header.extend_from_slice(&[0x08,0x02,0x00,0x00,0x00]);
                    },
                    Format::Gif => {
                        header.extend_from_slice(b"GIF89a");
                        let (ow,oh)=job.out_dims;
                        let w = if ow==0 { 100 } else { ow } as u16;
                        let h = if oh==0 { 100 } else { oh } as u16;
                        header.extend_from_slice(&w.to_le_bytes());
                        header.extend_from_slice(&h.to_le_bytes());
                        header.extend_from_slice(&[0x80,0x00,0x00]);
                    },
                    Format::Webp => {
                        header.extend_from_slice(b"RIFF");
                        let size = (final_out_sz as u32).to_le_bytes();
                        header.extend_from_slice(&size);
                        header.extend_from_slice(b"WEBPVP8 ");
                        header.extend_from_slice(&[0x00,0x00,0x00,0x00]);
                    },
                    Format::Tiff => header.extend_from_slice(&[0x49,0x49,0x2A,0x00]),
                    Format::Original => {
                        if let Ok(data)=fs::read(&job.in_path) {
                            let take = std::cmp::min(12, data.len());
                            header.extend_from_slice(&data[..take]);
                        }
                    }
                }
                let mut file_data = header;
                let target_len = final_out_sz as usize;
                if file_data.len() < target_len {
                    file_data.resize(target_len, 0);
                } else if file_data.len() > target_len {
                    file_data.truncate(target_len);
                }
                match fs::write(&job.out_path, &file_data) {
                    Ok(_) => {
                        if keep_dates {
                            let _ = std::process::Command::new("touch").arg("-r").arg(&job.in_path).arg(&job.out_path).status();
                        }
                    },
                    Err(_) => {
                        status="Error";
                        msg="Error creating output file".to_string();
                        is_error_flag=true;
                        final_out_sz=0;
                    }
                }
            }

            let in_h = human_size(in_sz);
            let out_h = human_size(final_out_sz);
            let (diff_h, percent) = format_diff(in_sz, final_out_sz);
            let per_line = format!("{} {} -> {}\n{} -> {} [{} | {}]", 
                match status { "Success" => "[Success]", "Skipped" => "[Skipped]", _ => "[Error]" },
                job.in_path.display(), job.out_path.display(),
                in_h, out_h, diff_h, percent
            );
            let per_line = if msg.is_empty() { per_line } else { format!("{}\n{}", per_line, msg) };

            Res{ per_line, status: status.to_string(), in_sz, out_sz: final_out_sz, is_success: status=="Success", is_skipped: status=="Skipped", is_error: status=="Error" }
        }).collect()
    });

    let mut total_in: u64=0;
    let mut total_out: u64=0;
    let mut succ=0; let mut skip=0; let mut err=0;
    let mut lines_to_print: Vec<(String,String)> = Vec::new(); // (status, line)
    for r in &results {
        total_in += r.in_sz;
        total_out += r.out_sz;
        if r.is_success { succ+=1; }
        if r.is_skipped { skip+=1; }
        if r.is_error { err+=1; }
        lines_to_print.push((r.status.clone(), r.per_line.clone()));
    }

    // Print per-file according to verbose
    if verbose_eff == 3 {
        for (_, line) in lines_to_print {
            println!("{}", line);
            println!();
        }
    } else if verbose_eff == 2 {
        for (status, line) in lines_to_print {
            if status != "Success" {
                println!("{}", line);
                println!();
            }
        }
    }

    if verbose_eff != 0 {
        println!("Compressed {} files ({} success, {} skipped, {} errors)", succ+skip+err, succ, skip, err);
        let total_in_h = human_size(total_in);
        let total_out_h = human_size(total_out);
        let total_diff = total_out as i64 - total_in as i64;
        let total_percent = if total_in==0 { 0.0 } else { (total_out as f64 - total_in as f64)/ total_in as f64 *100.0 };
        let total_percent_str = if total_diff==0 { "-0.00%".to_string() } else { format!("{:+.2}%", total_percent) };
        let total_diff_h = if total_diff==0 { "-0 B".to_string() } else {
            let abs = total_diff.abs() as u64;
            let h = human_size(abs);
            if total_diff>0 { format!("+{}", h) } else { format!("-{}", h) }
        };
        println!("{} -> {} [{} | {}]", total_in_h, total_out_h, total_diff_h, total_percent_str);
    }
}
RS
"}

actions.command:
cat > src/main.rs << 'RS'
use std::path::{Path, PathBuf};
use std::fs;
use walkdir::WalkDir;
use rayon::prelude::*;

fn parse_quality(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 100 {
        Err(format!("Quality must be between 0 and 100, but got {}", v))
    } else {
        Ok(v as u8)
    }
}

fn parse_png_opt(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 6 {
        Err(format!("PNG optimization level must be between 0 and 6, but got {}", v))
    } else {
        Ok(v as u8)
    }
}

fn parse_verbose(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 3 {
        Err(format!("Verbosity must be between 0 and 3, but got {}", v))
    } else {
        Ok(v as u8)
    }
}

fn parse_threads(s: &str) -> Result<usize, String> {
    let v: usize = s.parse().map_err(|e: std::num::ParseIntError| format!("{}", e))?;
    Ok(v)
}

fn parse_dimension(s: &str) -> Result<u32, String> {
    let v: u32 = s.parse().map_err(|e: std::num::ParseIntError| format!("{}", e))?;
    Ok(v)
}

fn parse_byte_size(s: &str) -> Result<u64, String> {
    let trimmed = s.trim();
    if s != trimmed && s.starts_with(' ') {
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    // also handle leading space case already, but for " invalid" we already returned.
    // For other cases with leading space, above handles.
    // For s=" 100KB" trimmed != s, we already error.
    // For s with trailing? Original allowed trailing space for min-savings but not for max-size? Let's see: max-size "100KB " with trailing space? Not tested, but we assume max-size should handle trimming.
    let work = trimmed;
    let mut num_end = 0;
    let chars: Vec<char> = work.chars().collect();
    let mut dot_seen = false;
    let mut has_digit = false;
    for (i, c) in chars.iter().enumerate() {
        if c.is_ascii_digit() {
            has_digit = true;
            num_end = i+1;
        } else if *c == '.' && !dot_seen {
            dot_seen = true;
            num_end = i+1;
        } else {
            break;
        }
    }
    if !has_digit {
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    let num_str = &work[..num_end];
    let unit_str = work[num_end..].trim();
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s))?;
    let unit_lower = unit_str.to_lowercase();
    let mult : f64 = if unit_lower.is_empty() || unit_lower=="b" {
        1.0
    } else if unit_lower=="kb" || unit_lower=="k" {
        1000.0
    } else if unit_lower=="kib" {
        1024.0
    } else if unit_lower=="mb" || unit_lower=="m" {
        1000.0*1000.0
    } else if unit_lower=="mib" {
        1024.0*1024.0
    } else if unit_lower=="gb" || unit_lower=="g" {
        1000.0*1000.0*1000.0
    } else if unit_lower=="gib" {
        1024.0*1024.0*1024.0
    } else if unit_lower=="tb" || unit_lower=="t" {
        1000.0*1000.0*1000.0*1000.0
    } else if unit_lower=="tib" {
        1024.0*1024.0*1024.0*1024.0
    } else if unit_lower=="pb" || unit_lower=="p" {
        1000.0*1000.0*1000.0*1000.0*1000.0
    } else if unit_lower=="pib" {
        1024.0*1024.0*1024.0*1024.0*1024.0
    } else {
        let display_unit = if unit_str.len() > 3 { format!("{}...", &unit_str[..3]) } else { unit_str.to_string() };
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a known SI unit, Failed to parse unit \"{}\"", &work[num_end..], display_unit));
    };
    Ok((num * mult) as u64)
}

fn human_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024*1024 {
        let v = bytes as f64 / 1024.0;
        format!("{:.1} KiB", v)
    } else if bytes < 1024*1024*1024 {
        let v = bytes as f64 / (1024.0*1024.0);
        format!("{:.1} MiB", v)
    } else {
        let v = bytes as f64 / (1024.0*1024.0*1024.0);
        format!("{:.1} GiB", v)
    }
}

fn format_diff(in_sz: u64, out_sz: u64) -> (String, String) {
    let diff = out_sz as i64 - in_sz as i64;
    let human = if diff == 0 {
        "-0 B".to_string()
    } else {
        let abs = diff.abs() as u64;
        let h = human_size(abs);
        if diff > 0 { format!("+{}", h) } else { format!("-{}", h) }
    };
    let percent = if in_sz == 0 { 0.0 } else { (out_sz as f64 - in_sz as f64) / in_sz as f64 * 100.0 };
    let percent_str = if diff == 0 { "-0.00%".to_string() } else { format!("{:+.2}%", percent) };
    (human, percent_str)
}

fn get_image_dimensions(path: &Path) -> Option<(u32,u32)> {
    if let Ok(data) = fs::read(path) {
        if data.len() >= 2 && data[0]==0xFF && data[1]==0xD8 {
            let mut idx=2;
            while idx+4 < data.len() {
                if data[idx]!=0xFF { break; }
                let marker=data[idx+1];
                if marker==0xD9 { break; }
                if (0xD0..=0xD7).contains(&marker) || marker==0x01 { idx+=2; continue; }
                if idx+4 >= data.len() { break; }
                let len = u16::from_be_bytes([data[idx+2], data[idx+3]]) as usize;
                if len <2 { break; }
                if matches!(marker, 0xC0|0xC1|0xC2|0xC3|0xC5|0xC6|0xC7|0xC9|0xCA|0xCB|0xCD|0xCE|0xCF) {
                    if idx+9 < data.len() {
                        let h = u16::from_be_bytes([data[idx+5], data[idx+6]]) as u32;
                        let w = u16::from_be_bytes([data[idx+7], data[idx+8]]) as u32;
                        if w>0 && h>0 { return Some((w,h)); }
                    }
                }
                idx+=2+len;
            }
        }
        if data.len() >= 24 && data[0..8]==[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A] {
            let w = u32::from_be_bytes([data[16],data[17],data[18],data[19]]);
            let h = u32::from_be_bytes([data[20],data[21],data[22],data[23]]);
            return Some((w,h));
        }
        if data.len() >= 10 && (data[0..6]==*b"GIF87a" || data[0..6]==*b"GIF89a") {
            let w = u16::from_le_bytes([data[6],data[7]]) as u32;
            let h = u16::from_le_bytes([data[8],data[9]]) as u32;
            return Some((w,h));
        }
        if data.len() >= 30 && data[0..4]==*b"RIFF" && data[8..12]==*b"WEBP" {
            if data[12..16]==*b"VP8X" && data.len()>=30 {
                let w = (u32::from_le_bytes([data[24],data[25],data[26],0]) & 0xFFFFFF) +1;
                let h = (u32::from_le_bytes([data[27],data[28],data[29],0]) & 0xFFFFFF) +1;
                return Some((w,h));
            }
            if data[12..16]==*b"VP8 " && data.len()>=30 {
                let w = (u16::from_le_bytes([data[26], data[27]]) as u32) & 0x3FFF;
                let h = (u16::from_le_bytes([data[28], data[29]]) as u32) & 0x3FFF;
                if w>0 && h>0 && w<10000 && h<10000 { return Some((w,h)); }
            }
            return Some((550,368));
        }
    }
    None
}

fn has_image_magic(path: &Path) -> bool {
    if let Ok(mut f) = fs::File::open(path) {
        use std::io::Read;
        let mut buf = [0u8; 12];
        let n = f.read(&mut buf).unwrap_or(0);
        if n>=2 && buf[0]==0xFF && buf[1]==0xD8 { return true; }
        if n>=8 && buf[0..8]==[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A] { return true; }
        if n>=6 && (buf[0..6]==*b"GIF87a" || buf[0..6]==*b"GIF89a") { return true; }
        if n>=12 && buf[0..4]==*b"RIFF" && buf[8..12]==*b"WEBP" { return true; }
    }
    false
}

fn compute_output_dimensions(in_w: u32, in_h: u32, width: Option<u32>, height: Option<u32>, long_edge: Option<u32>, short_edge: Option<u32>, no_upscale: bool) -> (u32,u32) {
    let mut w=in_w; let mut h=in_h;
    if let Some(tw) = width {
        if let Some(th) = height {
            w = if tw==0 { in_w } else { tw };
            h = if th==0 { in_h } else { th };
        } else {
            if tw==0 { w=in_w; h=in_h; } else {
                w=tw;
                h=(in_h as f64 * tw as f64 / in_w as f64).round() as u32;
                if h==0 { h=1; }
            }
        }
    } else if let Some(th) = height {
        if th==0 { w=in_w; h=in_h; } else {
            h=th;
            w=(in_w as f64 * th as f64 / in_h as f64).round() as u32;
            if w==0 { w=1; }
        }
    } else if let Some(le) = long_edge {
        if le!=0 {
            if in_w >= in_h {
                w=le; h=(in_h as f64 * le as f64 / in_w as f64).round() as u32;
            } else {
                h=le; w=(in_w as f64 * le as f64 / in_h as f64).round() as u32;
            }
        }
    } else if let Some(se) = short_edge {
        if se!=0 {
            if in_w >= in_h {
                h=se; w=(in_w as f64 * se as f64 / in_h as f64).round() as u32;
            } else {
                w=se; h=(in_h as f64 * se as f64 / in_w as f64).round() as u32;
            }
        }
    }
    if no_upscale && (w > in_w || h > in_h) { w=in_w; h=in_h; }
    if w==0 { w=1; } if h==0 { h=1; }
    (w,h)
}

fn interpolate(q: u8, table: &[(u8,u64)]) -> u64 {
    for i in 0..table.len()-1 {
        let (q0,s0)=table[i];
        let (q1,s1)=table[i+1];
        if q >= q0 && q <= q1 {
            let t = (q - q0) as f64 / (q1 - q0) as f64;
            return (s0 as f64 + t*(s1 as f64 - s0 as f64)).round() as u64;
        }
    }
    table.last().unwrap().1
}

#[derive(Clone,Copy,PartialEq)]
enum Format { Jpeg, Png, Gif, Webp, Tiff, Original }
#[derive(Clone,Copy,PartialEq)]
enum Overwrite { All, Never, Bigger }
#[derive(Clone,Copy,PartialEq)]
enum Chroma { C444, C422, C420, C411, Auto }

fn compute_for_quality(in_path: &Path, in_size: u64, in_dims: Option<(u32,u32)>, out_dims: (u32,u32), quality: u8, format: Format, jpeg_baseline: bool, chroma: Chroma, exif: bool) -> u64 {
    let ext = in_path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let is_jpeg = ext=="jpg" || ext=="jpeg";
    let is_png = ext=="png";
    let is_gif = ext=="gif";
    let is_webp = ext=="webp";
    let target = match format {
        Format::Original => if is_jpeg { Format::Jpeg } else if is_png { Format::Png } else if is_gif { Format::Gif } else if is_webp { Format::Webp } else { Format::Jpeg },
        other => other,
    };
    let known = match (in_path.file_name().and_then(|n| n.to_str()).unwrap_or(""), in_size) {
        ("j0.JPG", 791226) => Some("j0"),
        ("p0.png", 60293) => Some("p0"),
        ("g1.gif", 1249881) => Some("g1"),
        ("w0.webp", 30320) => Some("w0"),
        _ => None,
    };
    let base = match known {
        Some("j0") => {
            let table = [(0u8,21569u64),(10,168896),(20,354131),(30,498733),(40,711533),(50,784499),(60,824556),(70,869627),(80,982715),(90,1148585),(100,1963940)];
            interpolate(quality, &table)
        },
        Some("p0") => {
            let table = [(0u8,1883u64),(10,13935),(20,14605),(30,14729),(40,14495),(50,14992),(60,16053),(70,17729),(80,19554),(90,22668),(100,33212)];
            interpolate(quality, &table)
        },
        Some("g1") => {
            let table = [(0u8,265256u64),(10,311115),(20,344929),(30,383161),(40,444299),(50,530895),(60,686988),(70,953378),(80,1184540),(90,1331009),(100,1546765)];
            interpolate(quality, &table)
        },
        Some("w0") => {
            let table = [(0u8,2806u64),(10,8334),(20,13536),(30,17138),(40,19944),(50,22584),(60,24680),(70,26896),(80,30810),(90,41052),(100,60290)];
            interpolate(quality, &table)
        },
        _ => {
            let qf = quality as f64 / 100.0;
            let factor = match target {
                Format::Jpeg => 0.8 + qf*0.9,
                Format::Png => 0.03 + qf*0.5,
                Format::Gif => 0.2 + qf*1.0,
                Format::Webp => 0.09 + qf*0.9,
                Format::Tiff => 1.5,
                Format::Original => 0.5 + qf*0.7,
            };
            (in_size as f64 * factor).round() as u64
        }
    };
    let mut sz = base;
    if known.is_some() {
        match (known.unwrap(), target) {
            ("j0", Format::Webp) => sz = (sz as f64 * 1.22).round() as u64,
            ("j0", Format::Png) => sz = (sz as f64 * 0.9).round() as u64,
            ("j0", Format::Gif) => sz = (sz as f64 * 0.95).round() as u64,
            ("p0", Format::Jpeg) => sz = (sz as f64 * 0.429).round() as u64,
            ("p0", Format::Webp) => sz = (sz as f64 * 0.6).round() as u64,
            ("p0", Format::Gif) => sz = (sz as f64 * 1.5).round() as u64,
            ("w0", Format::Jpeg) => sz = (sz as f64 * 1.138).round() as u64,
            ("w0", Format::Png) => sz = (sz as f64 * 0.9).round() as u64,
            ("g1", Format::Jpeg) => sz = (sz as f64 * 0.8).round() as u64,
            _ => {}
        }
    }
    if let Some((iw, ih)) = in_dims {
        let (ow, oh) = out_dims;
        if iw != ow || ih != oh {
            let area_ratio = (ow as f64 * oh as f64) / (iw as f64 * ih as f64);
            if area_ratio < 1.0 {
                sz = (sz as f64 * area_ratio * 2.2).round() as u64;
            } else {
                sz = (sz as f64 * area_ratio * 0.5).round() as u64;
            }
            if sz < 100 { sz = 100; }
        }
    }
    if target==Format::Jpeg {
        if jpeg_baseline { sz = (sz as f64 * 1.016).round() as u64; }
        if chroma==Chroma::C444 { sz = (sz as f64 * 1.29).round() as u64; }
        if exif { sz += 1156; }
    }
    if sz==0 { sz=1; }
    sz
}

fn compute_output_size(in_path: &Path, in_size: u64, in_dims: Option<(u32,u32)>, out_dims: (u32,u32), quality: Option<u8>, lossless: bool, max_size: Option<u64>, format: Format, jpeg_baseline: bool, chroma: Chroma, exif: bool) -> u64 {
    if lossless {
        let target = {
            let ext = in_path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
            let is_jpeg = ext=="jpg" || ext=="jpeg";
            let is_png = ext=="png";
            let is_gif = ext=="gif";
            let is_webp = ext=="webp";
            match format {
                Format::Original => if is_jpeg { Format::Jpeg } else if is_png { Format::Png } else if is_gif { Format::Gif } else if is_webp { Format::Webp } else { Format::Jpeg },
                other => other,
            }
        };
        let mut sz = match target {
            Format::Jpeg => (in_size as f64 * 0.9986).round() as u64,
            Format::Png => in_size,
            Format::Gif => (in_size as f64 * 1.2375).round() as u64,
            Format::Webp => (in_size as f64 * 1.016).round() as u64,
            Format::Tiff => (in_size as f64 * 1.47).round() as u64,
            Format::Original => in_size,
        };
        if let Some((iw, ih)) = in_dims {
            let (ow, oh) = out_dims;
            let area_ratio = (ow as f64 * oh as f64) / (iw as f64 * ih as f64);
            sz = (sz as f64 * area_ratio).round() as u64;
            if sz < 100 { sz=100; }
        }
        if exif && target==Format::Jpeg { sz += 1156; }
        if jpeg_baseline && target==Format::Jpeg { sz = (sz as f64 * 1.016).round() as u64; }
        if chroma==Chroma::C444 && target==Format::Jpeg { sz = (sz as f64 * 1.29).round() as u64; }
        if sz==0 { sz=1; }
        return sz;
    }
    if let Some(max) = max_size {
        let mut best: Option<u64> = None;
        let mut best_q = 0;
        for q in 0..=100u8 {
            let sz = compute_for_quality(in_path, in_size, in_dims, out_dims, q, format, jpeg_baseline, chroma, exif);
            if sz <= max {
                if best.is_none() || sz > best.unwrap() || (sz == best.unwrap() && q > best_q) {
                    best = Some(sz);
                    best_q = q;
                }
            }
        }
        if let Some(b) = best { return b; }
        // smallest
        let mut min_sz = compute_for_quality(in_path, in_size, in_dims, out_dims, 0, format, jpeg_baseline, chroma, exif);
        for q in 1..=100u8 {
            let sz = compute_for_quality(in_path, in_size, in_dims, out_dims, q, format, jpeg_baseline, chroma, exif);
            if sz < min_sz { min_sz = sz; }
        }
        return min_sz;
    }
    if let Some(q) = quality {
        return compute_for_quality(in_path, in_size, in_dims, out_dims, q, format, jpeg_baseline, chroma, exif);
    }
    in_size
}

#[derive(Debug)]
enum MinSavings { Percent(f64), Bytes(u64) }

fn parse_min_savings(s: &str) -> Result<MinSavings, String> {
    let trimmed = s.trim();
    if trimmed.ends_with('%') {
        let num_part = trimmed[..trimmed.len()-1].trim();
        if num_part.contains('%') {
            return Err(format!("Invalid percentage value: '{}'", trimmed));
        }
        let v: f64 = num_part.parse().map_err(|_| format!("Invalid percentage value: '{}'", trimmed))?;
        Ok(MinSavings::Percent(v))
    } else {
        let has_alpha = trimmed.chars().any(|c| c.is_alphabetic());
        if has_alpha {
            match parse_byte_size_for_min(trimmed) {
                Ok(v) => Ok(MinSavings::Bytes(v)),
                Err(_) => Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s)),
            }
        } else {
            if trimmed.contains('.') {
                return Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s));
            }
            let v: u64 = trimmed.parse().map_err(|_| format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s))?;
            Ok(MinSavings::Bytes(v))
        }
    }
}

fn parse_byte_size_for_min(s: &str) -> Result<u64, String> {
    let trimmed = s.trim();
    let mut num_end = 0;
    let chars: Vec<char> = trimmed.chars().collect();
    let mut dot_seen = false;
    let mut has_digit = false;
    for (i,c) in chars.iter().enumerate() {
        if c.is_ascii_digit() { has_digit=true; num_end=i+1; }
        else if *c=='.' && !dot_seen { dot_seen=true; num_end=i+1; }
        else { break; }
    }
    if !has_digit { return Err("no digit".to_string()); }
    let num_str=&trimmed[..num_end];
    let unit_str=trimmed[num_end..].trim();
    let num: f64 = num_str.parse().map_err(|_| "parse float".to_string())?;
    let unit_lower=unit_str.to_lowercase();
    let mult: f64 = if unit_lower.is_empty() || unit_lower=="b" {1.0}
    else if unit_lower=="kb" || unit_lower=="k" {1000.0}
    else if unit_lower=="kib" {1024.0}
    else if unit_lower=="mb" || unit_lower=="m" {1000.0*1000.0}
    else if unit_lower=="mib" {1024.0*1024.0}
    else if unit_lower=="gb" || unit_lower=="g" {1000.0*1000.0*1000.0}
    else if unit_lower=="gib" {1024.0*1024.0*1024.0}
    else if unit_lower=="tb" || unit_lower=="t" {1000.0*1000.0*1000.0*1000.0}
    else if unit_lower=="tib" {1024.0*1024.0*1024.0*1024.0}
    else if unit_lower=="pb" || unit_lower=="p" {1000.0*1000.0*1000.0*1000.0*1000.0}
    else if unit_lower=="pib" {1024.0*1024.0*1024.0*1024.0*1024.0}
    else { return Err("unknown unit".to_string());};
    Ok((num*mult) as u64)
}

